const body = $input.first().json.body || $input.first().json;
const events = body.events || [];
const rows = [];

for (const evt of events) {
  const d = evt.data || {};
  rows.push({
    timestamp: evt.ts || new Date().toISOString(),
    sessionId: evt.sid || '',
    event: evt.event || '',
    mode: d.mode || '',
    topic: d.topic || '',
    score: d.score !== undefined ? d.score : '',
    total: d.total !== undefined ? d.total : '',
    pct: d.pct !== undefined ? d.pct : '',
    xp: d.xp !== undefined ? d.xp : '',
    submission: d.submission !== undefined ? String(d.submission).slice(0, 5000) : '',
    extra: JSON.stringify(d).slice(0, 2000)
  });
}

return rows.map(r => ({ json: r }));

const events = $input.all().map(i => i.json);
const now = new Date();
const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

const recent = events.filter(e => {
  if (!e.Timestamp) return false;
  const t = new Date(e.Timestamp);
  return !isNaN(t) && t >= dayAgo;
});

const dateStr = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', timeZone: 'Asia/Bangkok' });

if (recent.length === 0) {
  // Jordan 2026-08-03: silence on no activity. Only email when she actually opened it.
  return [];
}

const sessions = new Set(recent.map(e => e['Session ID']).filter(Boolean)).size;
const submissions = recent.filter(e => e.Event === 'daily_submission');
const completions = recent.filter(e => e.Event === 'quiz_complete' || e.Event === 'flash_complete');
const scores = completions.filter(e => e.Percentage !== '' && e.Percentage !== undefined).map(e => parseInt(e.Percentage));
const avgScore = scores.length ? Math.round(scores.reduce((a,b) => a+b, 0) / scores.length) : 0;
const totalXP = completions.reduce((s, e) => s + (parseInt(e.XP) || 0), 0);
const scoreEmoji = avgScore >= 90 ? '🌟' : avgScore >= 70 ? '✅' : avgScore >= 50 ? '📈' : '💪';

let html = `
<div style=\"font-family:system-ui,sans-serif;max-width:600px;margin:0 auto;background:#0f0f1a;color:#e0e0e0;border-radius:12px;overflow:hidden\">
  <div style=\"background:linear-gradient(135deg,#ef4444,#f59e0b);padding:20px 24px;text-align:center\">
    <h1 style=\"margin:0;color:#fff;font-size:22px\">📺 Nephisa's YouTube Course Report</h1>
    <p style=\"margin:4px 0 0;color:#ffe;font-size:14px\">${dateStr}</p>
  </div>
  <div style=\"padding:24px\">
    <table style=\"width:100%;border-collapse:collapse\">
      <tr><td style=\"padding:8px;color:#aaa\">🔓 Sessions</td><td style=\"padding:8px;text-align:right;font-weight:bold;color:#fff\">${sessions}</td></tr>
      <tr><td style=\"padding:8px;color:#aaa\">${scoreEmoji} Avg Quiz Score</td><td style=\"padding:8px;text-align:right;font-weight:bold;color:${avgScore>=70?'#6ee7b7':avgScore>=50?'#f59e0b':'#ef4444'}\">${scores.length ? avgScore + '%' : 'no quiz today'}</td></tr>
      <tr><td style=\"padding:8px;color:#aaa\">⚡ XP Earned</td><td style=\"padding:8px;text-align:right;font-weight:bold;color:#f59e0b\">${totalXP}</td></tr>
      <tr><td style=\"padding:8px;color:#aaa\">📮 Work Submitted</td><td style=\"padding:8px;text-align:right;font-weight:bold;color:${submissions.length?'#6ee7b7':'#ef4444'}\">${submissions.length ? 'YES' : 'NO ⚠️'}</td></tr>
    </table>`;

if (scores.length > 0) {
  html += `<h3 style=\"color:#a78bfa;font-size:14px;margin:20px 0 8px\">📊 Quiz Results</h3>`;
  completions.filter(e => e.Percentage !== '').forEach(e => {
    const p = parseInt(e.Percentage);
    const barColor = p >= 70 ? '#6ee7b7' : p >= 50 ? '#f59e0b' : '#ef4444';
    html += `<div style=\"margin:6px 0\"><span style=\"color:#aaa;font-size:12px\">${e.Topic||'Quiz'} (${e.Score}/${e.Total})</span><div style=\"background:#2a2a4a;border-radius:4px;height:8px;margin-top:2px\"><div style=\"background:${barColor};height:8px;border-radius:4px;width:${Math.min(p,100)}%\"></div></div><span style=\"color:#fff;font-size:11px\">${p}%</span></div>`;
  });
}

if (submissions.length > 0) {
  html += `<h3 style=\"color:#6ee7b7;font-size:14px;margin:20px 0 8px\">📮 Today's Submission</h3>`;
  submissions.forEach(s => {
    let d = {};
    try { d = JSON.parse(s.Extra || '{}'); } catch(e) {}
    const esc = t => String(t||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');
    html += `<div style=\"background:#1a1a2e;border:1px solid #2a2a4a;border-radius:10px;padding:14px;margin:8px 0\">`;
    html += `<p style=\"margin:0 0 6px;color:#f59e0b;font-weight:bold;font-size:13px\">${esc(s.Topic)} &middot; self-rating ${esc(d.rating || '?')}/5 &middot; ${esc(d.minutes || '?')} min</p>`;
    html += `<p style=\"margin:0;color:#ddd;font-size:13px;line-height:1.5\">${esc(s.Submission)}</p>`;
    if (d.link) html += `<p style=\"margin:6px 0 0;font-size:12px\"><a href=\"${esc(d.link)}\" style=\"color:#3b82f6\">attached link</a></p>`;
    html += `</div>`;
  });
} else {
  html += `<div style=\"background:#1a1a2e;border:1px solid #ef4444;border-radius:10px;padding:14px;margin-top:16px\"><p style=\"margin:0;color:#ef4444;font-size:13px\">She practiced but did not submit work. The scorecard needs the submission, not just quiz time.</p></div>`;
}

html += `
    <p style=\"text-align:center;color:#666;font-size:11px;margin-top:24px\">Score today on the aptitude scorecard while it's fresh &middot; <a href=\"https://docs.google.com/spreadsheets/d/1hiq8_GgMdl9-t83GsqZqDsUulCSajPdf3EDp5SKiGrM\" style=\"color:#3b82f6\">Full Sheet</a></p>
  </div>
</div>`;

const subj = submissions.length
  ? `📺 YouTube Course — ${submissions[0].Topic || 'work'} submitted, ${scores.length ? avgScore + '% quiz avg' : 'no quiz'}`
  : `📺 YouTube Course — practiced but NO submission ⚠️`;

return [{ json: { subject: subj, body: html } }];
